    # Defensive access to observation
    resource_obs = observation.get('resources', [])
    other_players = observation.get('players', [])
    position = observation.get('position', [0, 0])
    goal_area = observation.get('goal_area', None)
    territory_map = observation.get('territory_map', [])

    # Initialize move
    dx, dy = 0, 0

    # Collect resource positions
    resource_positions = []
    for res in resource_obs:
        res_pos = res.get('position')
        if res_pos:
            resource_positions.append(res_pos)

    # Find nearest resource
    def dist(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])
    nearest_res = None
    min_dist = float('inf')
    for rp in resource_positions:
        d = dist(position, rp)
        if d < min_dist:
            min_dist = d
            nearest_res = rp

    # If resources are available, move towards nearest
    if nearest_res:
        dx = 0
        dy = 0
        delta_x = nearest_res[0] - position[0]
        delta_y = nearest_res[1] - position[1]
        if abs(delta_x) > abs(delta_y):
            dx = 1 if delta_x > 0 else -1 if delta_x < 0 else 0
        elif abs(delta_y) > 0:
            dy = 1 if delta_y > 0 else -1 if delta_y < 0 else 0
        else:
            dx, dy = 0, 0
    else:
        # No resources, pursue nearest player or stay
        other_positions = []
        for p in other_players:
            p_pos = p.get('position')
            if p_pos:
                other_positions.append(p_pos)
        if other_positions:
            # Pursue nearest opponent
            nearest_opponent = None
            min_d = float('inf')
            for ppos in other_positions:
                d = dist(position, ppos)
                if d < min_d:
                    min_d = d
                    nearest_opponent = ppos
            if nearest_opponent:
                delta_x = nearest_opponent[0] - position[0]
                delta_y = nearest_opponent[1] - position[1]
                dx = 1 if delta_x > 0 else -1 if delta_x < 0 else 0
                dy = 1 if delta_y > 0 else -1 if delta_y < 0 else 0
        else:
            # No opponents, default move (can be random but here fixed)
            dx, dy = 0, 0
    return [dx, dy]

